INSERT INTO `blocs_texte` (`id`, `code`, `nom`, `categorie`, `contenu`, `actif`, `created_at`, `updated_at`) VALUES
(1, 'formule_jugement', 'Formule : a rendu le jugement', 'formule', '<p>A rendu le jugement dont la teneur suit dans la cause ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 08:58:20'),
(2, 'reserves_qualites', 'Réserves sur les qualités', 'formule', '<p class=\"ql-align-justify\">Sans que les présentes qualités puissent nuire ni préjudicier en quoi que ce soit aux droits et intérêts respectifs des parties en cause, mais au contraire et sous les plus expresses réserves des faits et de droit ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 08:58:20'),
(3, 'visa_deliberation', 'Visa : après en avoir délibéré', 'visas', '<p>Après en avoir délibéré conformément à la loi ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 08:58:20'),
(4, 'visa_loi_successions', 'Visa : loi relative aux successions', 'visas', '<p>Vu la loi n°2019-573 du 26 juin 2019 relative aux successions ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 08:58:20'),
(5, 'visa_pieces_rg', 'Visa : pièces du dossier de la procédure', 'visas', '<p>Vu les pièces du dossier de la procédure RG {{ numero_rg }} du {{ date_rg|date_numerique }} ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 09:54:47'),
(6, 'depens_requerant', 'Motif : dépens à la charge du requérant', 'depens', '<p class=\"ql-align-justify\">Attendu que la présente décision ayant été rendue au profit du requérant, il sied de mettre les dépens à sa charge ;</p>', 1, '2026-11-01 08:58:20', '2026-11-01 08:58:20'),
(7, 'cloture_jugement', 'Clôture du jugement', 'cloture', '<p>Ainsi fait, jugé et prononcé publiquement les jour, mois et an que dessus ;</p><p><br></p><p><strong>ET ONT SIGNE LE PRESIDENT ET LE GREFFIER./.</strong></p>', 1, '2026-11-01 08:58:20', '2026-11-01 10:22:40');
