INSERT INTO `chambres` (`id`, `annee_judiciaire_id`, `section_id`, `groupe`, `libelle`, `intitule`, `attributions`, `remarque`, `ordre`, `actif`, `created_at`, `updated_at`) VALUES
(1, 2, 1, NULL, '1re chambre civile', 'Présidentielle et administrative', 'Toutes instances en matière civile et commerciale dont l\'intérêt pécuniaire excède 100 000 000 FCFA (responsabilité délictuelle et contractuelle, contrats civils, créances civiles, action en garantie, résolution et résiliation de contrats publics…) ; contentieux administratifs et fiscaux, dettes publiques, expropriation pour cause d\'utilité publique, exequatur, propriété intellectuelle, recours de plein contentieux contre l\'administration ; toutes les procédures que le Président du Tribunal juge nécessaire de connaître.', 'Juges chargés de la mise en état : tous les membres de la chambre.', 1, 1, '2026-10-29 13:26:59', '2026-10-29 14:00:15'),
(2, 2, 1, NULL, '2e chambre civile', 'Immobilière et des paiements', 'Expropriation, copropriété, domaine foncier rural et urbain, baux emphytéotiques, revendication de propriété, empiètements, droits réels, baux à construction, servitudes, publicité foncière ; vente d\'immeubles, indemnités d\'occupation, déguerpissement, sûretés immobilières, baux d\'habitation et professionnels, validation de congé, expulsion et paiement de loyers, hypothèque conservatoire, saisies et ventes immobilières ; toutes instances en paiement dont l\'intérêt pécuniaire est inférieur ou égal à 100 000 000 FCFA, oppositions à ordonnance d\'injonction de payer, de délivrer, de restituer et de taxe, prestation de serment.', 'Juges chargés de la mise en état : tous les membres de la chambre.', 2, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(3, 2, 1, NULL, '3e chambre civile', 'Affaires familiales et état des personnes', NULL, NULL, 3, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(4, 2, 1, NULL, '4e chambre civile', 'Tutelles', 'Tutelle, puissance paternelle, émancipation, pension alimentaire, administration légale, garde juridique, tous certificats relevant de la compétence du juge des tutelles, procédures d\'urgence en matière de famille et d\'état des personnes.', NULL, 4, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(5, 2, 1, NULL, '5e chambre civile', 'Urgence', NULL, NULL, 5, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(6, 2, 3, 'Les juridictions criminelles', 'Tribunal criminel', NULL, 'Infractions commises par des individus renvoyés devant lui par l\'arrêt de renvoi de la chambre d\'instruction criminelle.', NULL, 6, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(7, 2, 3, 'Les juridictions criminelles', 'Tribunal criminel pour mineurs', NULL, 'Crimes commis par les mineurs âgés de 16 ans au moins.', NULL, 7, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(8, 2, 3, 'Les juridictions correctionnelles', '1re chambre correctionnelle', 'Délits économiques et financiers et délits divers', 'Délits économiques et financiers : vols simples et aggravés, recel, escroquerie, abus de confiance, abus de blanc-seing, faux et usage de faux, contrefaçon, fraude commerciale, concurrence déloyale, infractions bancaires, douanières, fiscales et forestières, blanchiment de capitaux, usure, cybercriminalité, code de l\'électricité… Délits divers : attentats aux mœurs, rébellion, délits de presse, diffamation et injures, coups et blessures volontaires, violences, homicides et blessures involontaires, stupéfiants, armes à feu, débits de boisson, contraventions de simple police connexes, réparations dues aux victimes après relaxe.', NULL, 8, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(9, 2, 3, 'Les juridictions correctionnelles', '2e chambre correctionnelle', 'Flagrants délits', 'Infractions de toute nature, poursuivies suivant la procédure de flagrant délit.', NULL, 9, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(10, 2, 3, 'Les juridictions correctionnelles', '3e chambre correctionnelle', NULL, NULL, NULL, 10, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(11, 2, 3, 'Les juridictions correctionnelles', '4e chambre correctionnelle', 'Tribunal pour enfants', NULL, NULL, 11, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(12, 2, 3, NULL, 'Juridiction présidentielle', NULL, 'Procédures correctionnelles à juge unique : homologation des procès-verbaux de transaction (art. 17 du code de procédure pénale) et des peines proposées dans le cadre de la comparution sur reconnaissance préalable de culpabilité (art. 521 et suivants).', NULL, 12, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(13, 2, 3, NULL, 'Juridiction de l\'application des peines', NULL, 'Juge de l\'application des peines.', NULL, 13, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(14, 2, 4, NULL, '1er cabinet d\'instruction', NULL, 'Instruction des affaires pénales (adultes).', NULL, 14, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(15, 2, 4, NULL, '2e cabinet d\'instruction', NULL, 'Instruction des affaires pénales (adultes).', NULL, 15, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(16, 2, 4, NULL, 'Cabinet du juge des enfants', NULL, 'Instruction des affaires concernant les mineurs.', NULL, 16, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
