(13, 9, NULL, NULL, NULL, 1, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(14, 10, 'Formation A', 'Tribunal de simple police', 'Contraventions de toute nature, amende de composition.', 1, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(15, 10, 'Formation B', 'Police de la circulation', 'Jugement des délits en matière de police de la circulation.', 2, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(16, 11, 'Tribunal pour enfants', NULL, 'Toutes les affaires relatives à l\'enfance délinquante.', 1, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
(17, 11, 'Juge des enfants', 'Juridiction unique', 'Juge des enfants, juridiction unique.', 2, 1, '2026-10-29 13:26:59', '2026-10-29 13:26:59'),
