DROP TABLE IF EXISTS `journal_audit`;
CREATE TABLE IF NOT EXISTS `journal_audit` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED DEFAULT NULL,
  `action` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cible_type` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cible_id` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `libelle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avant` json DEFAULT NULL,
  `apres` json DEFAULT NULL,
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `navigateur` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `journal_audit_cible_type_cible_id_index` (`cible_type`,`cible_id`),
  KEY `journal_audit_user_id_index` (`user_id`),
  KEY `journal_audit_action_index` (`action`),
  KEY `journal_audit_created_at_index` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

