--
-- Déclencheurs `journal_audit`
--
DROP TRIGGER IF EXISTS `journal_audit_no_delete`;
DELIMITER $$
CREATE TRIGGER `journal_audit_no_delete` BEFORE DELETE ON `journal_audit` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Journal non modifiable'
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `journal_audit_no_update`;
DELIMITER $$
CREATE TRIGGER `journal_audit_no_update` BEFORE UPDATE ON `journal_audit` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Journal non modifiable'
$$
DELIMITER ;

